  revokeApiToken(id,userId){this.db.prepare('UPDATE api_tokens SET revoked_at=? WHERE id=? AND user_id=? AND revoked_at IS NULL').run(this.now(),id,userId);return this.getApiToken(id,userId);}
  createOAuthState(userId,provider,state,expiresAt,metadata={}){this.db.prepare('DELETE FROM oauth_states WHERE user_id=? AND provider=?').run(userId,provider);const id=randomUUID();this.db.prepare('INSERT INTO oauth_states(id,user_id,provider,state,expires_at,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').run(id,userId,provider,state,expiresAt,JSON.stringify(metadata),this.now());return id;}
  consumeOAuthState(provider,state){const x=this.db.prepare('SELECT * FROM oauth_states WHERE provider=? AND state=? AND expires_at>?').get(provider,state,this.now());this.db.prepare('DELETE FROM oauth_states WHERE provider=? AND state=?').run(provider,state);return x?{...x,metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}:null;}
  createDeployment(userId,projectId,data={}){const id=randomUUID(),now=this.now();this.db.prepare('INSERT INTO deployments(id,user_id,project_id,provider,status,deployment_id,url,branch,commit_sha,error,metadata_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)').run(id,userId,projectId,String(data.provider),String(data.status||'queued'),data.deploymentId||null,data.url||null,data.branch||null,data.commitSha||null,data.error||null,JSON.stringify(data.metadata||{}),now,now);return this.getDeployment(id,userId);}
  getDeployment(id,userId){const x=this.db.prepare('SELECT * FROM deployments WHERE id=? AND user_id=?').get(id,userId);return x?{...x,metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}:null;}
  listDeployments(projectId,userId){return this.db.prepare('SELECT * FROM deployments WHERE project_id=? AND user_id=? ORDER BY created_at DESC').all(projectId,userId).map(x=>({...x,metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}));}
  updateDeployment(id,userId,patch={}){const fields=[],vals=[];for(const k of ['status','deployment_id','url','branch','commit_sha','error'])if(k in patch){fields.push(k+'=?');vals.push(patch[k]);}if('metadata' in patch){fields.push('metadata_json=?');vals.push(JSON.stringify(patch.metadata||{}));}if(!fields.length)return this.getDeployment(id,userId);fields.push('updated_at=?');vals.push(this.now(),id,userId);this.db.prepare('UPDATE deployments SET '+fields.join(',')+' WHERE id=? AND user_id=?').run(...vals);return this.getDeployment(id,userId);}
  createProjectAsset(projectId,userId,{id=randomUUID(),name,mime,kind,role='other',size,sha256,publicPath,metadata={}}={}){
    if(!this.getProject(projectId,userId))throw new Error('Project not found');const now=this.now();
    this.db.prepare('INSERT INTO project_assets(id,project_id,user_id,name,mime,kind,role,size,sha256,public_path,metadata_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)').run(id,projectId,userId,String(name),String(mime||'application/octet-stream'),String(kind||'binary'),String(role||'other'),Number(size||0),String(sha256||''),String(publicPath||''),JSON.stringify(metadata&&typeof metadata==='object'?metadata:{}),now,now);
    return this.getProjectAsset(id,projectId,userId);
  }
  getProjectAsset(id,projectId,userId){const x=this.db.prepare('SELECT * FROM project_assets WHERE id=? AND project_id=? AND user_id=?').get(id,projectId,userId);return x?({...x,metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}):null;}
  listProjectAssets(projectId,userId){if(!this.getProject(projectId,userId))return [];return this.db.prepare('SELECT * FROM project_assets WHERE project_id=? AND user_id=? ORDER BY created_at DESC').all(projectId,userId).map(x=>({...x,metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}));}
