  getVisualBaseline(projectId,userId,route){if(!this.getProject(projectId,userId))return null;return this.db.prepare('SELECT * FROM visual_baselines WHERE project_id=? AND user_id=? AND route=?').get(projectId,userId,String(route))||null;}
  listVisualBaselines(projectId,userId){if(!this.getProject(projectId,userId))return [];return this.db.prepare('SELECT * FROM visual_baselines WHERE project_id=? AND user_id=? ORDER BY route').all(projectId,userId);}
  upsertVisualBaseline(projectId,userId,{route,storedPath,size,sha256,width=null,height=null}={}){if(!this.getProject(projectId,userId))throw new Error('Project not found');const now=this.now(),existing=this.getVisualBaseline(projectId,userId,route);if(existing)this.db.prepare('UPDATE visual_baselines SET stored_path=?,size=?,sha256=?,width=?,height=?,updated_at=? WHERE id=? AND project_id=? AND user_id=?').run(storedPath,Number(size||0),sha256,Number.isFinite(Number(width))?Number(width):null,Number.isFinite(Number(height))?Number(height):null,now,existing.id,projectId,userId);else this.db.prepare('INSERT INTO visual_baselines(id,project_id,user_id,route,stored_path,size,sha256,width,height,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(randomUUID(),projectId,userId,String(route),String(storedPath),Number(size||0),String(sha256||''),Number.isFinite(Number(width))?Number(width):null,Number.isFinite(Number(height))?Number(height):null,now,now);return this.getVisualBaseline(projectId,userId,route);}
  getProjectContent(projectId,userId){
    const project=this.getProject(projectId,userId);if(!project)return null;
    const row=this.db.prepare('SELECT content_json FROM project_content WHERE project_id=?').get(projectId);
    if(!row)return null;
    try{return JSON.parse(row.content_json)}catch{return null}
  }
  upsertProjectContent(projectId,userId,content){
    const project=this.getProject(projectId,userId);if(!project)throw new Error('Project not found');
    const normalized=content&&typeof content==='object'?content:{};
    const now=this.now();
    this.db.prepare('INSERT INTO project_content(project_id,user_id,content_json,updated_at) VALUES (?,?,?,?) ON CONFLICT(project_id) DO UPDATE SET user_id=excluded.user_id,content_json=excluded.content_json,updated_at=excluded.updated_at').run(projectId,userId,JSON.stringify(normalized),now);
    this.db.prepare('UPDATE projects SET updated_at=? WHERE id=?').run(now,projectId);
    return this.getProjectContent(projectId,userId);
  }
  createSession(userId,projectId,title='New build'){const p=this.getProject(projectId,userId);if(!p)throw new Error('Project not found');const id=randomUUID(),now=this.now();this.db.prepare('INSERT INTO sessions VALUES (?,?,?,?,?,?)').run(id,projectId,userId,String(title).slice(0,120),now,now);return this.getSession(id,userId);}
  getSession(id,userId){return this.db.prepare("SELECT s.* FROM sessions s JOIN projects p ON p.id=s.project_id WHERE s.id=? AND (s.user_id=? OR p.user_id=? OR EXISTS (SELECT 1 FROM workspace_members wm WHERE wm.workspace_id=p.workspace_id AND wm.user_id=? AND wm.status='active'))").get(id,userId,userId,userId)||null;}
  listSessions(projectId,userId){if(!this.getProject(projectId,userId))return [];return this.db.prepare('SELECT * FROM sessions WHERE project_id=? ORDER BY updated_at DESC').all(projectId);}
  createRun(userId,sessionId,request,targetId='web-node'){const id=randomUUID(),now=this.now();this.db.prepare('INSERT INTO runs(id,session_id,user_id,status,request,target_id,spec_json,workspace,preview_url,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(id,sessionId,userId,'running',request,targetId,null,null,null,now,now);return this.getRun(id,userId);}
  updateRun(id,userId,patch){const run=this.getRun(id,userId);if(!run)throw new Error('Run not found');const allowed=['status','target_id','spec_json','workspace','preview_url'];const fields=[],vals=[];for(const k of allowed)if(k in patch){fields.push(`${k}=?`);vals.push(patch[k]);}fields.push('updated_at=?');vals.push(this.now(),id,userId);this.db.prepare(`UPDATE runs SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);return this.getRun(id,userId);}
  getRun(id,userId){return this.db.prepare("SELECT r.* FROM runs r JOIN sessions s ON s.id=r.session_id JOIN projects p ON p.id=s.project_id WHERE r.id=? AND (r.user_id=? OR p.user_id=? OR EXISTS (SELECT 1 FROM workspace_members wm WHERE wm.workspace_id=p.workspace_id AND wm.user_id=? AND wm.status='active'))").get(id,userId,userId,userId)||null;}
  listRuns(sessionId,userId){if(!this.getSession(sessionId,userId))return [];return this.db.prepare('SELECT * FROM runs WHERE session_id=? ORDER BY created_at DESC').all(sessionId);}
  createChangeset(runId,{status='proposed',summary='',operations=[]}){const id=randomUUID();this.db.prepare('INSERT INTO changesets VALUES (?,?,?,?,?,?,?)').run(id,runId,status,summary,JSON.stringify(operations),null,this.now());return this.getChangeset(id);}
  getChangeset(id){return this.db.prepare('SELECT * FROM changesets WHERE id=?').get(id)||null;}
  listChangesets(runId){return this.db.prepare('SELECT * FROM changesets WHERE run_id=? ORDER BY created_at').all(runId).map(x=>({...x,operations:x.operations_json?JSON.parse(x.operations_json):[]}));}
  updateChangeset(id,patch){const fields=[],vals=[];for(const k of ['status','summary','commit_sha','operations_json'])if(k in patch){fields.push(`${k}=?`);vals.push(k==='operations_json'&&typeof patch[k]!=='string'?JSON.stringify(patch[k]):patch[k]);}if(!fields.length)return this.getChangeset(id);vals.push(id);this.db.prepare(`UPDATE changesets SET ${fields.join(',')} WHERE id=?`).run(...vals);return this.getChangeset(id);}
  addEvidence(runId,type,payload){const id=randomUUID();this.db.prepare('INSERT INTO evidence VALUES (?,?,?,?,?)').run(id,runId,type,JSON.stringify(payload??null),this.now());return {id,runId,type,payload};}
