  listEvents(runId,userId){const ok=this.getRun(runId,userId);if(!ok)return [];return this.db.prepare('SELECT * FROM run_events WHERE run_id=? ORDER BY created_at').all(runId).map(x=>({...x,payload:x.payload_json?JSON.parse(x.payload_json):null}));}
  toolCall(runId,tool,permission,input,before,after,result){const id=randomUUID();this.db.prepare('INSERT INTO tool_calls VALUES (?,?,?,?,?,?,?,?,?)').run(id,runId,tool,permission,JSON.stringify(input??null),JSON.stringify(before??null),JSON.stringify(after??null),JSON.stringify(result??null),this.now());return id;}
  upsertRunner({id=randomUUID(),name,capability,labels=[],metadata={},status='ready'}={}){const now=this.now();const exists=this.db.prepare('SELECT id FROM runner_nodes WHERE id=?').get(id);if(exists)this.db.prepare('UPDATE runner_nodes SET name=?,capability=?,labels_json=?,metadata_json=?,status=?,last_heartbeat=?,updated_at=? WHERE id=?').run(String(name),String(capability),JSON.stringify(labels),JSON.stringify(metadata),String(status),now,now,id);else this.db.prepare('INSERT INTO runner_nodes(id,name,capability,labels_json,metadata_json,status,last_heartbeat,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)').run(id,String(name),String(capability),JSON.stringify(labels),JSON.stringify(metadata),String(status),now,now,now);return this.getRunner(id);}
  heartbeatRunner(id,{status='ready',metadata}={}){const now=this.now();const fields=['status=?','last_heartbeat=?','updated_at=?'];const vals=[String(status),now,now];if(metadata!==undefined){fields.push('metadata_json=?');vals.push(JSON.stringify(metadata));}vals.push(id);this.db.prepare(`UPDATE runner_nodes SET ${fields.join(',')} WHERE id=?`).run(...vals);return this.getRunner(id);}
  getRunner(id){const r=this.db.prepare('SELECT * FROM runner_nodes WHERE id=?').get(id);return r?({...r,labels:r.labels_json?JSON.parse(r.labels_json):[],metadata:r.metadata_json?JSON.parse(r.metadata_json):{}}):null;}
