  createTask({id=randomUUID(),runId,key,title,phase='lifecycle',status='pending',dependencies=[],metadata={}}={}){const now=this.now();this.db.prepare('INSERT INTO agent_tasks(id,run_id,key,title,phase,status,dependencies_json,metadata_json,started_at,finished_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').run(id,runId,String(key),String(title),String(phase),String(status),JSON.stringify(dependencies),JSON.stringify(metadata),status==='running'?now:null,null,now,now);return this.getTask(id);}
  getTask(id){const x=this.db.prepare('SELECT * FROM agent_tasks WHERE id=?').get(id);return x?this.hydrateTask(x):null;}
  getTaskByKey(runId,key){const x=this.db.prepare('SELECT * FROM agent_tasks WHERE run_id=? AND key=?').get(runId,key);return x?this.hydrateTask(x):null;}
