  hydrateTask(x){return {...x,dependencies:x.dependencies_json?JSON.parse(x.dependencies_json):[],metadata:x.metadata_json?JSON.parse(x.metadata_json):{}};}
  updateTask(id,patch={}){const t=this.getTask(id);if(!t)throw new Error('Task not found');const fields=[],vals=[];for(const k of ['status','phase','title','started_at','finished_at'])if(k in patch){fields.push(`${k}=?`);vals.push(patch[k]);}if('dependencies' in patch){fields.push('dependencies_json=?');vals.push(JSON.stringify(patch.dependencies));}if('metadata' in patch){fields.push('metadata_json=?');vals.push(JSON.stringify(patch.metadata));}if(!fields.length)return t;fields.push('updated_at=?');vals.push(this.now(),id);this.db.prepare(`UPDATE agent_tasks SET ${fields.join(',')} WHERE id=?`).run(...vals);return this.getTask(id);}
  saveRepositoryIndex(runId,index){const now=this.now();this.db.prepare('INSERT INTO repository_indexes(run_id,index_json,created_at,updated_at) VALUES (?,?,?,?) ON CONFLICT(run_id) DO UPDATE SET index_json=excluded.index_json,updated_at=excluded.updated_at').run(runId,JSON.stringify(index),now,now);return index;}
