  createDependencyRequest(runId,dependencies=[]){const existing=this.db.prepare('SELECT * FROM dependency_requests WHERE run_id=? ORDER BY created_at DESC LIMIT 1').get(runId);if(existing&&existing.status==='approved')return existing;const id=randomUUID(),now=this.now();this.db.prepare('INSERT INTO dependency_requests(id,run_id,dependencies_json,status,created_at,updated_at) VALUES (?,?,?,?,?,?)').run(id,runId,JSON.stringify(dependencies),'pending',now,now);return this.getDependencyRequest(id);}
