  getLatestDependencyRequest(runId){const x=this.db.prepare('SELECT * FROM dependency_requests WHERE run_id=? ORDER BY created_at DESC LIMIT 1').get(runId);return x?{...x,dependencies:x.dependencies_json?JSON.parse(x.dependencies_json):[]}:null;}
  approveDependencyRequest(id,userId){const x=this.getDependencyRequest(id);if(!x)return null;const run=this.getRun(x.run_id,userId);if(!run)throw new Error('not_found');this.db.prepare("UPDATE dependency_requests SET status='approved',approved_at=?,approved_by=?,updated_at=? WHERE id=?").run(this.now(),userId,this.now(),id);return this.getDependencyRequest(id);}
  listDependencyRequests(runId,userId){if(!this.getRun(runId,userId))return [];return this.db.prepare('SELECT * FROM dependency_requests WHERE run_id=? ORDER BY created_at').all(runId).map(x=>({...x,dependencies:x.dependencies_json?JSON.parse(x.dependencies_json):[]}));}
  addUsage(runId,userId,usage={}){const id=randomUUID();this.db.prepare('INSERT INTO usage_events(id,run_id,user_id,provider,model,tier,input_tokens,output_tokens,tool_calls,duration_ms,estimated_cost_usd,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').run(id,runId,userId,usage.provider||null,usage.model||null,usage.tier||null,Number(usage.inputTokens||0),Number(usage.outputTokens||0),Number(usage.toolCalls||0),Number(usage.durationMs||0),usage.estimatedCostUsd==null?null:Number(usage.estimatedCostUsd),this.now());return id;}
  listUsage(runId,userId){if(!this.getRun(runId,userId))return [];return this.db.prepare('SELECT * FROM usage_events WHERE run_id=? ORDER BY created_at').all(runId);}
  usageSummary(runId,userId){if(!this.getRun(runId,userId))return null;const x=this.db.prepare('SELECT COUNT(*) calls,COALESCE(SUM(input_tokens),0) input_tokens,COALESCE(SUM(output_tokens),0) output_tokens,COALESCE(SUM(tool_calls),0) tool_calls,COALESCE(SUM(duration_ms),0) duration_ms,SUM(estimated_cost_usd) estimated_cost_usd FROM usage_events WHERE run_id=?').get(runId);return {...x,estimated_cost_usd:x.estimated_cost_usd==null?null:Number(x.estimated_cost_usd)};}
  createCheckpoint(runId,name,pathValue,metadata={}){const id=randomUUID();this.db.prepare('INSERT INTO run_checkpoints(id,run_id,name,path,metadata_json,created_at) VALUES (?,?,?,?,?,?)').run(id,runId,String(name).slice(0,120),pathValue,JSON.stringify(metadata),this.now());return this.getCheckpoint(id);}
  createGoal(runId,{objective,completionCriteria=[],constraints=[],status='active',metadata={}}={}){const now=this.now(),id=randomUUID();this.db.prepare('INSERT INTO run_goals(id,run_id,objective,completion_criteria_json,constraints_json,status,metadata_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)').run(id,runId,String(objective||''),JSON.stringify(completionCriteria),JSON.stringify(constraints),status,JSON.stringify(metadata),now,now);return this.getGoal(runId);}
  getGoal(runId){const x=this.db.prepare('SELECT * FROM run_goals WHERE run_id=?').get(runId);return x?{...x,completionCriteria:x.completion_criteria_json?JSON.parse(x.completion_criteria_json):[],constraints:x.constraints_json?JSON.parse(x.constraints_json):[],metadata:x.metadata_json?JSON.parse(x.metadata_json):{}}:null;}
  updateGoal(runId,patch={}){const fields=[],vals=[];for(const k of ['objective','status'])if(k in patch){fields.push(`${k}=?`);vals.push(patch[k]);}if('completionCriteria' in patch){fields.push('completion_criteria_json=?');vals.push(JSON.stringify(patch.completionCriteria));}if('constraints' in patch){fields.push('constraints_json=?');vals.push(JSON.stringify(patch.constraints));}if('metadata' in patch){fields.push('metadata_json=?');vals.push(JSON.stringify(patch.metadata));}if(!fields.length)return this.getGoal(runId);fields.push('updated_at=?');vals.push(this.now(),runId);this.db.prepare(`UPDATE run_goals SET ${fields.join(',')} WHERE run_id=?`).run(...vals);return this.getGoal(runId);}
